    %dst_ptr = tt.addptr %dst_base, %idx : tensor<1024x!tt.ptr<f16>>, tensor<1024xi32>
    tt.store %dst_ptr, %out, %mask : tensor<1024x!tt.ptr<f16>>
    tt.return
  }
